+function BookmarkModal({ item, onClose, onSave }) {
+  const [form, setForm] = useState(item || { title: '', url: '', description: '', tags: '', collection: 'Read later' });
+  const update = (key, value) => setForm(f => ({ ...f, [key]: value }));
