font-size:20px;line-height:1.2;margin:7px 0 8px;flex:1}.title-link svg{margin-top:10px;opacity:0;transition:opacity .2s;color:#6e766f}.bookmark-card:hover .title-link svg{opacity:1}.card-main p{font-size:12px;line-height:1.6;color:#747a73;margin:0;min-height:58px}.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:16px}.tags span{font-size:10px;color:#5f6a61;background:#edece5;padding:4px 7px;border-radius:4px}.card-foot{border-top:1px solid #e5e3dc;padding:11px 18px;display:flex;justify-content:space-between;color:#8b908a;font-size:10px}.card-foot span,.card-foot button{display:flex;align-items:center;gap:5px}.card-foot button{border:0;background:transparent;font-size:10px;color:#92968f;cursor:pointer}.card-foot button:hover,.card-foot .is-read{color:#4f745d}.cards.list{display:flex;flex-direction:column;gap:10px}.bookmark-card.list{display:grid;grid-template-columns:64px 1fr 180px;align-items:center}.bookmark-card.list .card-top{padding:18px;display:block}.bookmark-card.list .card-actions{display:none}.bookmark-card.list .card-main{padding:15px 0}.bookmark-card.list .card-main p{min-height:0}.bookmark-card.list .tags{margin-top:10px}.bookmark-card.list .card-foot{height:100%;border-top:0;border-left:1px solid #e5e3dc;flex-direction:column;justify-content:center;align-items:start;gap:12px}.empty{text-align:center;padding:80px 20px}.empty>div{width:60px;height:60px;border-radius:50%;background:#e6e5dc;color:#6f7b72;display:grid;place-items:center;margin:auto}.empty h2{font-size:25px;margin:18px 0 5px}.empty p{color:#858a84;font-size:13px;margin:0 0 22px}.modal-backdrop{position:fixed;inset:0;background:#26312a66;display:grid;place-items:center;padding:20px;z-index:50;backdrop-filter:blur(3px)}.modal{width:min(560px,100%);background:#f8f6ef;border-radius:14px;padding:28px;box-shadow:0 30px 80px #1e272150}.modal-head{display:flex;justify-content:space-between;align-items:start;margin-bottom:22px}.modal h2{font-size:28px;margin:4px 0}.modal label{display:flex;flex-dir