:7px}.quick-filters button{display:flex;align-items:center;gap:6px;border:1px solid transparent;background:transparent;padding:7px 10px;border-radius:6px;font-size:12px;color:#787e77;cursor:pointer}.quick-filters button:hover{color:var(--ink)}.quick-filters .filter-active{border-color:#d2d1c8;background:#fbfaf6;color:#3d5045}.sort{font-size:12px;color:#8a8e88}.sort select{border:0;background:transparent;font-weight:600;color:#445047;outline:0;padding:0 3px}.cards.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.bookmark-card{background:var(--paper);border:1px solid #deddd5;border-radius:10px;box-shadow:0 3px 13px rgba(44,51,44,.035);transition:transform .18s,box-shadow .18s;position:relative}.bookmark-card:hover{transform:translateY(-2px);box-shadow:0 9px 25px rgba(44,51,44,.08)}.card-top{display:flex;justify-content:space-between;padding:18px 18px 0}.site-icon{width:35px;height:35px;border-radius:9px;background:color-mix(in srgb,var(--hue),white 78%);display:grid;place-items:center}.site-icon img{width:20px;height:20px;border-radius:4px}.card-actions{display:flex;gap:3px}.mini,.icon-button{border:0;background:transparent;color:#92958f;padding:6px;border-radius:6px;cursor:pointer}.mini:hover,.icon-button:hover{background:#eeeae2;color:#4f5851}.mini.active{color:#b75440}.menu-wrap{position:relative}.pop-menu{position:absolute;right:0;top:32px;background:#fffefb;border:1px solid #ddd9cf;border-radius:8px;padding:5px;min-width:135px;box-shadow:0 9px 30px #30352f20;z-index:5}.pop-menu button{border:0;background:transparent;display:block;width:100%;text-align:left;padding:8px;border-radius:5px;font-size:12px;cursor:pointer}.pop-menu button:hover{background:#f0ede6}.card-main{padding:15px 18px 19px}.domain{text-transform:uppercase;letter-spacing:1px;color:#9a9d97;font-size:9px;font-weight:600}.title-link{display:flex;color:var(--ink);text-decoration:none;align-items:start;gap:7px}.title-link h3{font-family:'DM Serif Display',serif;font-weight:400;font-size:20px;line-height:1.2;margin:7px 0 8px;flex:1}.title-link svg{margin-top:10px;opacity:0;transition:opacity .2s;color:#6e766f}.bookmark-card:hover .title-link svg{opacity:1}.card-main p{font-size:12px;line-height:1.6;color:#747a73;margin:0;min-height:58px}.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:16px}.tags span{font-size:10px;color:#5f6a61;background:#edece5;padding:4px 7px;border-radius:4px}.card-foot{border-top:1px solid #e5e3dc;padding:11px 18px;display:flex;justify-content:space-between;color:#8b908a;font-size:10px}.card-foot span,.card-foot button{display:flex;align-items:center;gap:5px}.card-foot button{border:0;background:transparent;font-size:10px;color:#92968f;cursor:pointer}.card-foot button:hover,.card-foot .is-read{color:#4f745d}.cards.list{display:flex;flex-direction:column;gap:10px}.bookmark-card.list{display:grid;grid-template-columns:64px 1fr 180px;align-items:center}.bookmark-card.list .card-top{padding:18px;display:block}.bookmark-card.list .card-actions{display:none}.bookmark-card.list .card-main{padding:15px 0}.bookmark-card.list .card-main p{min-height:0}.bookmark-card.list .tags{margin-top:10px}.bookmark-card.list .card-foot{height:100%;border-top:0;border-left:1px solid #e5e3dc;flex-direction:column;justify-content:center;align-items:start;gap:12px}.empty{text-align:center;padding:80px 20px}.empty>div{width:60px;height:60px;border-radius:50%;background:#e6e5dc;color:#6f7b72;display:grid;place-items:center;margin:auto}.empty h2{font-size:25px;margin:18px 0 5px}.empty p{color:#858a84;font-size:13px;margin:0 0 22px}.modal-backdrop{position:fixed;inset:0;background:#26312a66;display:grid;place-items:center;padding:20px;z-index:50;backdrop-filter:blur(3px)}.modal{width:min(560px,100%);background:#f8f6ef;border-radius:14px;padding:28px;box-shadow:0 30px 80px #1e272150}.modal-head{display:flex;justify-content:space-between;align-items:start;margin-bottom:22px}.modal h2{font-size:28px;margin:4px 0}.modal label{display:flex;flex-dir